{
  "name": "llm_le_state_check",
  "confidence": "medium",
  "docstring": "Checks BLE link-layer/vif state and prepares the appropriate HCI response or reconnection/scan initialization path.",
  "subsystem": "ble",
  "var_renames": {
    "v4": "vif_idx",
    "v8": "response_buf",
    "v9": "vif_table_base",
    "v10": "vif_ctxt",
    "v12": "hci_cmd_state",
    "v16": "event_state",
    "v18": "mode_flag",
    "v21": "reassoc_request"
  },
  "struct_hints": [
    {
      "offset": 61,
      "meaning": "caller message vif index"
    },
    {
      "offset": 48,
      "meaning": "caller message flags word; bit 0x20 indicates reassociation request"
    },
    {
      "offset": 59,
      "meaning": "caller message event/state byte"
    },
    {
      "offset": 54,
      "meaning": "16-bit event payload length starting at +64"
    },
    {
      "offset": 64,
      "meaning": "caller message event payload, including six-byte address"
    },
    {
      "offset": 106,
      "meaning": "vif context status byte used as busy/scan condition"
    },
    {
      "offset": 108,
      "meaning": "vif context active/ready byte"
    },
    {
      "offset": 116,
      "meaning": "vif context address type or state sentinel; 0xff appears invalid"
    },
    {
      "offset": 72,
      "meaning": "vif context 32-bit channel/connection context pointer"
    }
  ]
}
